import type { IScannerComponents } from '../types';

export const defaultComponents: IScannerComponents = {
	finder: true,
	torch: true,
	tracker: undefined,
	onOff: false,
	zoom: false,
};
export const defaultConstraints: MediaTrackConstraints = {
	facingMode: 'environment',
	width: { min: 640, ideal: 720, max: 1920 },
	height: { min: 640, ideal: 720, max: 1080 },
};
import type { IScannerStyles } from '../types';

export const defaultStyles: IScannerStyles = {
	container: {
		width: '100%',
		height: '100%',
		position: 'relative',
		display: 'flex',
		alignItems: 'center',
		justifyContent: 'center',
		overflow: 'hidden',
		aspectRatio: '1/1',
	},
	video: {
		width: '100%',
		height: '100%',
		objectFit: 'cover',
		overflow: 'hidden',
	},
};
import type { IDetectedBarcode } from '../types';

export function outline(
	detectedCodes: IDetectedBarcode[],
	ctx: CanvasRenderingContext2D,
) {
	for (const detectedCode of detectedCodes) {
		const [firstPoint, ...otherPoints] = detectedCode.cornerPoints;

		ctx.lineWidth = 2;
		ctx.strokeStyle = 'yellow';

		ctx.beginPath();
		ctx.moveTo(firstPoint.x, firstPoint.y);

		for (const { x, y } of otherPoints) {
			ctx.lineTo(x, y);
		}

		ctx.lineTo(firstPoint.x, firstPoint.y);
		ctx.closePath();
		ctx.stroke();
	}
}

export function boundingBox(
	detectedCodes: IDetectedBarcode[],
	ctx: CanvasRenderingContext2D,
) {
	for (const detectedCode of detectedCodes) {
		const {
			boundingBox: { x, y, width, height },
		} = detectedCode;

		ctx.lineWidth = 2;
		ctx.strokeStyle = 'yellow';
		ctx.strokeRect(x, y, width, height);
	}
}

export function centerText(
	detectedCodes: IDetectedBarcode[],
	ctx: CanvasRenderingContext2D,
) {
	detectedCodes.forEach((detectedCode) => {
		const { boundingBox, rawValue } = detectedCode;
		const centerX = boundingBox.x + boundingBox.width / 2;
		const centerY = boundingBox.y + boundingBox.height / 2;
		const fontSize = Math.max(12, (50 * boundingBox.width) / ctx.canvas.width);
		const lineHeight = fontSize;

		ctx.font = `${fontSize}px sans-serif`;
		ctx.textAlign = 'left';

		let formattedText: string;

		try {
			formattedText = JSON.stringify(JSON.parse(rawValue), null, 2);
		} catch {
			formattedText = rawValue;
		}

		const lines = formattedText.split('\n');
		const textWidth = Math.max(
			...lines.map((line) => ctx.measureText(line).width),
		);
		const textHeight = lines.length * lineHeight;
		const padding = 10;
		const rectX = centerX - textWidth / 2 - padding;
		const rectY = centerY - textHeight / 2 - padding;
		const rectWidth = textWidth + padding * 2;
		const rectHeight = textHeight + padding;
		const radius = 8;

		ctx.beginPath();
		ctx.moveTo(rectX + radius, rectY);
		ctx.lineTo(rectX + rectWidth - radius, rectY);
		ctx.quadraticCurveTo(
			rectX + rectWidth,
			rectY,
			rectX + rectWidth,
			rectY + radius,
		);
		ctx.lineTo(rectX + rectWidth, rectY + rectHeight - radius);
		ctx.quadraticCurveTo(
			rectX + rectWidth,
			rectY + rectHeight,
			rectX + rectWidth - radius,
			rectY + rectHeight,
		);
		ctx.lineTo(rectX + radius, rectY + rectHeight);
		ctx.quadraticCurveTo(
			rectX,
			rectY + rectHeight,
			rectX,
			rectY + rectHeight - radius,
		);
		ctx.lineTo(rectX, rectY + radius);
		ctx.quadraticCurveTo(rectX, rectY, rectX + radius, rectY);
		ctx.closePath();
		ctx.fillStyle = 'rgba(255, 255, 0, 0.9)';
		ctx.fill();

		lines.forEach((line, index) => {
			const y =
				centerY + index * lineHeight - ((lines.length - 1) * lineHeight) / 2;
			let currentX = centerX - textWidth / 2;
			let lastIndex = 0;

			const propertyMatches = [...line.matchAll(/"([^"]+)":/g)];
			const valueMatches = [
				...line.matchAll(/:\s*("[^"]*"|\d+|true|false|null)/g),
			];

			propertyMatches.forEach((match, matchIndex) => {
				const property = match[0].replace(':', '');
				const beforeProperty = line.substring(lastIndex, match.index);

				ctx.fillStyle = 'black';
				ctx.fillText(beforeProperty, currentX, y);
				currentX += ctx.measureText(beforeProperty).width;

				ctx.fillStyle = 'blue';
				ctx.fillText(property, currentX, y);
				currentX += ctx.measureText(property).width;

				lastIndex = match.index + property.length;

				ctx.fillStyle = 'black';
				ctx.fillText(': ', currentX, y);
				currentX += ctx.measureText(': ').width;

				if (matchIndex < valueMatches.length) {
					const valueMatch = valueMatches[matchIndex];
					const beforeValue = line.substring(lastIndex, valueMatch.index);

					ctx.fillStyle = 'black';
					ctx.fillText(beforeValue, currentX, y);
					currentX += ctx.measureText(beforeValue).width;

					const value = valueMatch[0].match(/:\s*(.*)/)?.[1] ?? '';
					ctx.fillStyle = 'green';
					ctx.fillText(value, currentX, y);
					currentX += ctx.measureText(value).width;

					lastIndex = valueMatch.index + valueMatch[0].length;
				}
			});

			ctx.fillStyle = 'black';
			const remainingLine = line.substring(lastIndex);
			ctx.fillText(remainingLine, currentX, y);
		});
	});
}
export default (value: unknown): value is Date => value instanceof Date;
export default (value: unknown): value is null | undefined => value == null;
import isDateObject from './isDateObject';
import isNullOrUndefined from './isNullOrUndefined';

export const isObjectType = (value: unknown) => typeof value === 'object';

export default <T extends object>(value: unknown): value is T =>
	!isNullOrUndefined(value) &&
	!Array.isArray(value) &&
	isObjectType(value) &&
	!isDateObject(value);
import isNullOrUndefined from './isNullOrUndefined';
import { isObjectType } from './isObject';

type Primitive = null | undefined | string | number | boolean | symbol | bigint;

export default (value: unknown): value is Primitive =>
	isNullOrUndefined(value) || !isObjectType(value);
import isObject from '../utilities/isObject';

import isDateObject from './isDateObject';
import isPrimitive from './isPrimitive';

export default function deepEqual(object1: unknown, object2: unknown) {
	if (isPrimitive(object1) || isPrimitive(object2)) return object1 === object2;

	if (isDateObject(object1) && isDateObject(object2))
		return object1.getTime() === object2.getTime();

	const obj1 = object1 as Record<string, unknown>;
	const obj2 = object2 as Record<string, unknown>;

	const keys1 = Object.keys(obj1);
	const keys2 = Object.keys(obj2);

	if (keys1.length !== keys2.length) return false;

	for (const key of keys1) {
		const val1 = obj1[key];

		if (!keys2.includes(key)) return false;

		if (key !== 'ref') {
			const val2 = obj2[key];

			if (
				(isDateObject(val1) && isDateObject(val2)) ||
				(isObject(val1) && isObject(val2)) ||
				(Array.isArray(val1) && Array.isArray(val2))
					? !deepEqual(val1, val2)
					: val1 !== val2
			)
				return false;
		}
	}

	return true;
}
